.home-page {
  overflow: clip;
}

.home-hero {
  position: relative;
  min-height: min(46rem, calc(100svh - 5.5rem));
  display: flex;
  align-items: center;
  overflow: hidden;
  border-bottom: 1px solid var(--colour-border);
  background:
    linear-gradient(90deg, transparent 0 68%, var(--colour-surface-soft) 68% 100%),
    var(--colour-canvas);
}

.home-hero::after {
  content: '';
  position: absolute;
  right: 0;
  bottom: 0;
  width: min(18rem, 26vw);
  border-bottom: 0.55rem solid var(--colour-brand);
}

.home-hero__crease {
  position: absolute;
  top: 0;
  bottom: 0;
  left: calc(50% + 7rem);
  width: 2px;
  background: var(--colour-border);
  pointer-events: none;
}

.home-hero__layout {
  display: grid;
  grid-template-columns: minmax(0, 0.9fr) minmax(28rem, 1.1fr);
  align-items: center;
  gap: clamp(2rem, 5vw, 6rem);
  padding-block: var(--space-16);
}

.home-hero__content {
  position: relative;
  z-index: 2;
}

.home-hero h1 {
  max-width: 10ch;
  font-size: clamp(4rem, 7vw, 6.25rem);
  line-height: 0.9;
  letter-spacing: -0.02em;
}

.home-hero h1::after {
  content: '';
  display: block;
  width: 5rem;
  margin-top: var(--space-5);
  border-bottom: 3px solid var(--colour-primary);
}

.home-hero__summary {
  max-width: 35rem;
  margin: var(--space-6) 0 0;
  color: var(--colour-text-secondary);
  font-size: 1.125rem;
  line-height: 1.65;
}

.home-hero__actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-3);
  margin-top: var(--space-8);
}

.home-hero__actions .button,
.home-cta .button {
  min-height: 3rem;
  padding-inline: var(--space-5);
}

.home-hero__player-link {
  display: inline-flex;
  gap: var(--space-2);
  margin-top: var(--space-5);
  color: var(--colour-link);
  font-weight: 600;
  text-underline-offset: 0.2em;
}

.home-hero__visual {
  position: relative;
  min-width: 0;
  aspect-ratio: 1.08;
  overflow: hidden;
  border: 1px solid var(--colour-border);
  border-radius: var(--radius-large);
  background: var(--colour-surface);
  box-shadow: var(--shadow-card);
  clip-path: polygon(0 0, 100% 0, 100% 92%, 92% 100%, 0 100%);
  isolation: isolate;
}

.home-hero__visual::before {
  content: '';
  position: absolute;
  z-index: 0;
  inset: 0;
  background:
    linear-gradient(var(--colour-border) 1px, transparent 1px),
    linear-gradient(90deg, var(--colour-border) 1px, transparent 1px);
  background-size: 4rem 4rem;
  opacity: 0.22;
}

.hero-scene-fallback,
.hero-scene {
  position: absolute;
  z-index: 1;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  pointer-events: none;
}

.hero-scene-fallback {
  padding: 1.5rem;
  opacity: 1;
  transition: opacity var(--motion-standard) var(--ease-fast);
}

.hero-scene {
  opacity: 0;
  touch-action: pan-y;
  transition: opacity var(--motion-standard) var(--ease-fast);
}

.home-hero__visual--enhanced .hero-scene-fallback {
  opacity: 0;
}

.home-hero__visual--enhanced .hero-scene {
  opacity: 1;
}

.hero-scene[data-context-state='lost'],
.home-hero__visual--enhanced .hero-scene[data-context-state='lost'] {
  opacity: 0;
  transition: none;
}

.hero-scene-fallback__pitch path:first-child {
  fill: var(--colour-surface-raised);
  stroke: var(--colour-border);
  stroke-width: 2;
}

.hero-scene-fallback__crease,
.hero-scene-fallback__stumps {
  fill: none;
  stroke: var(--colour-text);
  stroke-width: 5;
}

.hero-scene-fallback__trail {
  fill: none;
  stroke: var(--colour-primary);
  stroke-linecap: round;
  stroke-width: 9;
  stroke-dasharray: 9 14;
  opacity: 0.72;
  animation: hero-trail 1.8s var(--ease-hit) infinite;
}

.hero-scene-fallback__ball {
  fill: var(--colour-primary);
  stroke: var(--colour-primary-ink);
  stroke-width: 2;
}

.hero-scene-fallback__marker {
  fill: none;
  stroke: var(--colour-brand);
  stroke-width: 5;
}

.hero-scene-fallback__connection {
  fill: none;
  stroke: var(--colour-data-accent);
  stroke-width: 3;
}

.hero-scene-fallback__derived rect {
  fill: var(--colour-data-accent);
}

.hero-scene-fallback__derived rect:first-child {
  fill: var(--colour-brand);
}

.home-hero__visual-caption {
  position: absolute;
  z-index: 3;
  top: var(--space-5);
  left: var(--space-5);
  display: grid;
  gap: var(--space-1);
  max-width: 15rem;
  padding: var(--space-3);
  border-inline-start: 3px solid var(--colour-primary);
  background: var(--colour-surface);
  box-shadow: var(--shadow-card);
}

.home-hero__visual-caption span,
.home-hero__visual-caption small {
  color: var(--colour-text-muted);
  font-size: 0.7rem;
}

.home-hero__visual-caption span {
  font-weight: 600;
  text-transform: uppercase;
}

.home-hero__visual-caption strong {
  font-family: var(--font-display);
  font-size: 1.1rem;
}

@keyframes hero-trail {
  from {
    stroke-dashoffset: 46;
  }
  to {
    stroke-dashoffset: 0;
  }
}

.home-principles,
.explore-gateway {
  padding-block: clamp(4rem, 8vw, 7rem);
  background: var(--colour-surface);
}

.home-section-heading {
  max-width: 45rem;
}

.home-section-heading h2 {
  font-size: clamp(2.5rem, 5vw, 4rem);
  line-height: 0.98;
}

.home-section-heading > p:last-child,
.home-section-heading > div > p {
  max-width: 42rem;
  margin: var(--space-4) 0 0;
  color: var(--colour-text-secondary);
  line-height: 1.6;
}

.home-section-heading--split {
  max-width: none;
  display: grid;
  grid-template-columns: minmax(10rem, 0.55fr) minmax(0, 1.45fr);
  gap: var(--space-8);
  padding-bottom: var(--space-8);
  border-bottom: 1px solid var(--colour-border);
}

.home-section-heading--split > .eyebrow {
  margin: var(--space-2) 0 0;
}

.home-principles__list,
.explore-gateway__list,
.api-feature__paths {
  margin: 0;
  padding: 0;
  list-style: none;
}

.home-principles__list {
  display: grid;
  grid-template-columns: 1.12fr 1fr 1fr;
}

.home-principles__list li {
  min-width: 0;
  padding: var(--space-10) var(--space-8) 0 0;
}

.home-principles__list li + li {
  padding-left: var(--space-8);
  border-inline-start: 1px solid var(--colour-border);
}

.home-principles__number {
  display: block;
  margin-bottom: var(--space-12);
  color: var(--colour-brand-text);
  font-family: var(--font-display);
  font-size: 1rem;
  font-weight: 700;
}

.home-principles__list h3 {
  font-size: clamp(2rem, 4vw, 3.5rem);
}

.home-principles__list p {
  max-width: 31ch;
  margin: var(--space-4) 0 0;
  color: var(--colour-text-secondary);
  line-height: 1.65;
}

.derivation-story {
  padding-block: clamp(4rem, 8vw, 7rem);
  border-block: 1px solid var(--colour-border);
  background: var(--colour-canvas);
}

.derivation-story__layout {
  display: grid;
  grid-template-columns: minmax(16rem, 0.62fr) minmax(0, 1.38fr);
  gap: clamp(3rem, 8vw, 8rem);
}

.derivation-story__heading {
  align-self: start;
  position: sticky;
  top: var(--space-8);
}

.derivation-flow {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 5rem minmax(0, 1fr);
  align-items: stretch;
  gap: var(--space-4);
}

.derivation-flow__event,
.derivation-flow__statistics {
  padding: var(--space-6);
  border: 1px solid var(--colour-border);
  background: var(--colour-surface);
  box-shadow: var(--shadow-card);
}

.derivation-flow__event {
  border-top: 3px solid var(--colour-brand);
}

.derivation-flow__statistics {
  border-top: 3px solid var(--colour-data-accent);
}

.derivation-flow__step {
  margin: 0 0 var(--space-3);
  color: var(--colour-text-muted);
  font-size: 0.72rem;
  font-weight: 600;
  text-transform: uppercase;
}

.derivation-flow h3 {
  font-size: 2rem;
}

.derivation-flow dl {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--space-2);
  margin: var(--space-6) 0;
}

.derivation-flow dl div {
  min-width: 0;
  padding-top: var(--space-3);
  border-top: 1px solid var(--colour-border);
}

.derivation-flow dt {
  color: var(--colour-text-muted);
  font-size: 0.7rem;
}

.derivation-flow dd {
  margin: var(--space-1) 0 0;
  font-family: var(--font-display);
  font-size: 2.25rem;
  font-variant-numeric: tabular-nums;
  font-weight: 700;
}

.derivation-flow code,
.api-feature code {
  font-family: var(--font-mono);
}

.derivation-flow code {
  display: block;
  padding: var(--space-3);
  overflow-wrap: anywhere;
  background: var(--colour-surface-raised);
  color: var(--colour-text);
  font-size: 0.78rem;
}

.derivation-flow__transition {
  display: grid;
  place-content: center;
  gap: var(--space-2);
  color: var(--colour-label);
  font-size: 0.7rem;
  text-align: center;
  text-transform: uppercase;
}

.derivation-flow__transition span {
  position: relative;
  width: 100%;
  border-top: 2px solid var(--colour-primary);
}

.derivation-flow__transition span::after {
  content: '';
  position: absolute;
  top: -5px;
  right: 0;
  width: 8px;
  height: 8px;
  border-top: 2px solid var(--colour-primary);
  border-right: 2px solid var(--colour-primary);
  transform: rotate(45deg);
}

.derivation-flow__statistics ul {
  display: grid;
  gap: 0;
  margin: var(--space-5) 0 0;
  padding: 0;
  list-style: none;
}

.derivation-flow__statistics li {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--space-4);
  padding-block: var(--space-3);
  border-top: 1px solid var(--colour-border);
}

.derivation-flow__statistics li span {
  color: var(--colour-text-secondary);
  font-size: 0.82rem;
}

.derivation-flow__statistics li strong {
  font-family: var(--font-display);
  font-size: 1.75rem;
  font-variant-numeric: tabular-nums;
}

.derivation-flow__source {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: var(--space-5);
  padding: var(--space-5);
  border-bottom: 1px solid var(--colour-border);
  background: var(--colour-surface-soft);
}

.derivation-flow__source-mark {
  width: 0.9rem;
  height: 0.9rem;
  margin-top: var(--space-1);
  border: 3px solid var(--colour-primary);
  border-radius: 50%;
  box-shadow:
    0 0 0 4px var(--colour-surface),
    0 0 0 5px var(--colour-primary);
}

.derivation-flow__source strong {
  font-family: var(--font-display);
  font-size: 1.35rem;
}

.derivation-flow__source p:last-child {
  margin: var(--space-2) 0 0;
  color: var(--colour-text-secondary);
  line-height: 1.55;
}

.explore-gateway__list li {
  display: grid;
  grid-template-columns: 4rem minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--space-6);
  padding-block: var(--space-6);
  border-bottom: 1px solid var(--colour-border);
}

.explore-gateway__list > li > span {
  color: var(--colour-brand-text);
  font-family: var(--font-display);
  font-weight: 700;
}

.explore-gateway__list h3 {
  font-size: 2rem;
}

.explore-gateway__list p {
  max-width: 52rem;
  margin: var(--space-2) 0 0;
  color: var(--colour-text-secondary);
  line-height: 1.55;
}

.explore-gateway__list a {
  display: inline-flex;
  gap: var(--space-2);
  color: var(--colour-link);
  font-weight: 600;
  text-underline-offset: 0.2em;
}

.explore-gateway__teams {
  margin: var(--space-6) 0 0;
  color: var(--colour-text-secondary);
}

.explore-gateway__teams a {
  font-weight: 600;
}

.api-feature {
  padding-block: clamp(4rem, 8vw, 7rem);
  background: var(--colour-surface-soft);
}

.api-feature__layout {
  display: grid;
  grid-template-columns: minmax(18rem, 0.85fr) minmax(0, 1.15fr);
  gap: clamp(3rem, 8vw, 8rem);
}

.api-feature__paths {
  border-top: 3px solid var(--colour-data-accent);
  background: var(--colour-surface);
  box-shadow: var(--shadow-card);
}

.api-feature__paths li {
  display: grid;
  grid-template-columns: 2.5rem minmax(0, 1fr);
  gap: var(--space-2) var(--space-4);
  padding: var(--space-5);
  border-bottom: 1px solid var(--colour-border);
}

.api-feature__paths li > span {
  grid-row: 1 / span 2;
  color: var(--colour-brand-text);
  font-family: var(--font-display);
  font-weight: 700;
}

.api-feature__paths code {
  min-width: 0;
  overflow-wrap: anywhere;
  color: var(--colour-text);
  font-size: 0.8rem;
}

.api-feature__paths strong {
  color: var(--colour-text-secondary);
  font-size: 0.8rem;
  font-weight: 500;
}

.home-cta {
  position: relative;
  padding-block: clamp(4rem, 8vw, 6rem);
  overflow: hidden;
  background: var(--colour-surface-raised);
}

.home-cta::before {
  content: '';
  position: absolute;
  top: 0;
  bottom: 0;
  left: 24%;
  border-left: 3px solid var(--colour-primary);
  transform: skewX(-18deg);
}

.home-cta__layout {
  position: relative;
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: var(--space-8);
}

.home-cta h2 {
  max-width: 14ch;
  font-size: clamp(2.75rem, 6vw, 5rem);
  line-height: 0.95;
}

.site-footer {
  border-top: 1px solid var(--colour-border);
  background: var(--colour-surface-raised);
}

.site-footer__inner {
  min-height: 8rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
}

.site-footer p {
  margin: 0;
  color: var(--colour-text-secondary);
  font-size: 0.875rem;
}

.browse-page {
  min-height: 38rem;
  padding-bottom: 5rem;
}

.page-heading {
  padding-block: 2rem 1.5rem;
}

.page-heading h1 {
  max-width: 20ch;
  margin: 0;
  font-size: 3.25rem;
  line-height: 1;
  white-space: normal;
}

.page-heading > p:last-child {
  max-width: 47rem;
  margin: 1rem 0 0;
  color: var(--colour-text-secondary);
  font-size: 1.0625rem;
  line-height: 1.6;
}

.browse-page__content {
  display: grid;
  gap: 2rem;
}

.filter-panel {
  padding: 1.5rem;
  border: 1px solid var(--colour-border);
  border-radius: 6px;
  background: var(--colour-surface-raised);
}

.filter-panel__heading,
.results-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
}

.filter-panel h2,
.results-heading h2,
.related-records h2 {
  max-width: none;
  font-size: 1.5rem;
}

.text-link,
.back-link {
  color: var(--colour-link);
  font-weight: 650;
  text-underline-offset: 0.2em;
}

.filter-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1rem;
  margin-block: 1.25rem;
}

.field {
  display: grid;
  align-content: start;
  gap: 0.5rem;
  min-width: 0;
}

.field > span,
.field > label {
  color: var(--colour-text-secondary);
  font-size: 0.8125rem;
  font-weight: 650;
}

.field input,
.field select {
  width: 100%;
  min-width: 0;
  min-height: 2.75rem;
  padding: 0.625rem 0.75rem;
  border: 1px solid var(--colour-border);
  border-radius: 6px;
  background: var(--colour-surface);
  color: var(--colour-text);
}

.name-combobox {
  position: relative;
}

.name-combobox__control {
  position: relative;
  display: flex;
}

.name-combobox__control input {
  padding-right: 4.5rem;
}

.name-combobox__clear,
.name-combobox__toggle {
  position: absolute;
  top: 50%;
  min-height: 2rem;
  border: 0;
  background: transparent;
  color: var(--colour-link);
  cursor: pointer;
  transform: translateY(-50%);
}

.name-combobox__clear {
  right: 2rem;
  padding-inline: 0.375rem;
  font-size: 0.75rem;
  font-weight: 650;
}

.name-combobox__toggle {
  right: 0.25rem;
  width: 2rem;
  padding: 0;
  color: var(--colour-text);
}

.name-combobox__clear:focus-visible,
.name-combobox__toggle:focus-visible {
  outline-offset: 0;
}

.name-combobox__popover {
  position: absolute;
  z-index: 20;
  top: calc(100% + 0.25rem);
  right: 0;
  left: 0;
  overflow: hidden;
  border: 1px solid var(--colour-border);
  border-radius: 6px;
  background: var(--colour-surface);
  box-shadow: var(--shadow-overlay);
}

.name-combobox__options {
  max-height: 18rem;
  margin: 0;
  padding: 0.25rem;
  overflow-y: auto;
  list-style: none;
}

.name-combobox__option {
  display: grid;
  gap: 0.125rem;
  padding: 0.625rem 0.75rem;
  border-radius: 4px;
  cursor: pointer;
}

.name-combobox__option.is-active,
.name-combobox__option[aria-selected='true'] {
  background: var(--colour-primary-soft);
}

.name-combobox__option span {
  color: var(--colour-text);
  font-size: 0.9375rem;
  font-weight: 650;
}

.name-combobox__option small {
  color: var(--colour-text-secondary);
  font-size: 0.75rem;
  line-height: 1.4;
}

.name-combobox__option .name-combobox__selected-marker {
  color: var(--colour-text);
  font-weight: 650;
}

.name-combobox__state {
  margin: 0;
  padding: 0.875rem;
  color: var(--colour-text-secondary);
  font-size: 0.875rem;
  line-height: 1.5;
}

.name-combobox__state--error {
  border-left: 3px solid var(--colour-error);
  background: var(--colour-error-soft);
}

.name-combobox__state--error p {
  margin: 0;
}

.name-combobox__state .button {
  width: 100%;
  margin-top: 0.75rem;
}

.field-error {
  margin: 0;
  color: var(--colour-error);
  font-size: 0.8125rem;
  line-height: 1.4;
}

.active-filter-summary {
  margin-bottom: 1.25rem;
  padding: 1rem;
  border-left: 3px solid var(--colour-primary);
  background: var(--colour-surface);
}

.active-filter-summary h3 {
  margin: 0;
  font-size: 1rem;
}

.active-filter-summary ul {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 1.25rem;
  margin: 0.625rem 0 0;
  padding: 0;
  list-style: none;
}

.active-filter-summary li {
  color: var(--colour-text-secondary);
  font-size: 0.875rem;
}

.active-filter-summary li span {
  color: var(--colour-text);
  font-weight: 650;
}

.visually-hidden {
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  padding: 0 !important;
  margin: -1px !important;
  overflow: hidden !important;
  clip: rect(0, 0, 0, 0) !important;
  white-space: nowrap !important;
  border: 0 !important;
}

.button {
  display: inline-flex;
  min-height: 2.75rem;
  align-items: center;
  justify-content: center;
  padding: 0.625rem 1rem;
  border: 1px solid transparent;
  border-radius: 6px;
  cursor: pointer;
  font-weight: 700;
  text-decoration: none;
}

.button--primary {
  background: var(--colour-primary);
  color: var(--colour-surface);
}

:root[data-theme='night'] .button--primary {
  color: var(--colour-canvas);
}

.button--secondary {
  border-color: var(--colour-border);
  background: var(--colour-surface);
  color: var(--colour-text);
}

.button:hover {
  filter: brightness(0.94);
}

.results-region {
  min-width: 0;
}

.results-heading {
  padding-bottom: 1rem;
  border-bottom: 2px solid var(--colour-primary);
}

.results-heading p {
  margin: 0;
  color: var(--colour-text-muted);
  font-size: 0.875rem;
}

.record-list {
  margin: 0;
  padding: 0;
  list-style: none;
}

.record-list__item {
  display: grid;
  grid-template-columns: minmax(8rem, 0.7fr) minmax(0, 1.8fr) minmax(12rem, 1fr);
  align-items: center;
  gap: 1.5rem;
  padding-block: 1.5rem;
  border-bottom: 1px solid var(--colour-border);
}

.record-list__meta,
.record-list__summary {
  margin: 0;
  color: var(--colour-text-secondary);
  font-size: 0.875rem;
  line-height: 1.5;
}

.record-list__item h3 {
  min-width: 0;
}

.record-list__item h3 a {
  color: var(--colour-text);
  text-decoration-color: var(--colour-primary);
  text-decoration-thickness: 2px;
  text-underline-offset: 0.2em;
}

.state-message {
  margin-top: 1.5rem;
  padding: 1.5rem;
  border-left: 3px solid var(--colour-data-accent);
  background: var(--colour-surface-raised);
}

.state-message--error {
  border-left-color: var(--colour-error);
  background: var(--colour-error-soft);
}

.state-message h1,
.state-message h3,
.state-message p {
  max-width: 48rem;
}

.state-message h1,
.state-message h3 {
  margin: 0;
  white-space: normal;
}

.state-message p {
  margin: 0.75rem 0 0;
  color: var(--colour-text-secondary);
  line-height: 1.6;
}

.state-message .button {
  margin-top: 1rem;
}

.pagination {
  display: flex;
  justify-content: flex-end;
  padding-top: 1.5rem;
}

.pagination__end {
  margin: 1.5rem 0 0;
  color: var(--colour-text-muted);
  font-size: 0.875rem;
  text-align: right;
}

.detail-page {
  min-height: 38rem;
  padding-block: 2rem 5rem;
}

.page-heading--detail {
  padding-block: 1rem;
  border-bottom: 2px solid var(--colour-primary);
}

.record-facts {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0 2rem;
  margin: 0;
}

.record-facts > div {
  min-width: 0;
  padding-block: 1rem;
  border-bottom: 1px solid var(--colour-border);
}

.record-facts dt {
  color: var(--colour-text-muted);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
}

.record-facts dd {
  margin: 0.5rem 0 0;
  overflow-wrap: anywhere;
  font-family: var(--font-display);
  font-size: 1.375rem;
  font-weight: 700;
}

.related-records {
  margin-top: 2rem;
}

.related-collection {
  margin-top: 2rem;
}

.fixture-groups {
  margin: 0;
  padding: 0;
  list-style: none;
}

.fixture-groups > li > h3 {
  margin: 1.5rem 0 0;
  font-size: 1.25rem;
}

.record-fact-links {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 1rem;
}

.related-records > div {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem 1.5rem;
  margin-top: 1rem;
}

.related-records a {
  font-weight: 700;
  text-underline-offset: 0.2em;
}

.state-message--detail {
  margin-top: 2rem;
}

.statistics-summary,
.statistics-section {
  margin-top: 2rem;
}

.statistics-section-heading,
.statistic-card__heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1.5rem;
}

.statistics-section-heading {
  padding-bottom: 1rem;
  border-bottom: 2px solid var(--colour-primary);
}

.statistics-section-heading h2,
.statistics-section-heading h3,
.statistics-warnings h3,
.statistics-warnings h2 {
  max-width: none;
  margin: 0;
  font-size: 1.5rem;
}

.statistics-section-heading > p,
.statistics-section-heading > div > p,
.statistics-card__heading p,
.statistic-card__source-count,
.statistics-note,
.statistics-section__empty {
  color: var(--colour-text-secondary);
}

.statistics-section-heading > p,
.statistics-section-heading > div > p,
.statistic-card__heading p,
.statistic-card__source-count,
.statistics-note,
.statistics-section__empty {
  margin: 0;
}

.statistics-status {
  padding: 0.35rem 0.6rem;
  border: 1px solid var(--colour-border);
  border-radius: 999px;
  background: var(--colour-surface-raised);
  color: var(--colour-text);
  font-size: 0.8125rem;
  font-weight: 750;
  white-space: nowrap;
}

.statistics-status--partial {
  border-color: var(--colour-brand);
}

.statistics-warnings {
  margin-top: 2rem;
  padding: 1.5rem;
  border-left: 3px solid var(--colour-brand);
  background: var(--colour-surface-raised);
}

.statistics-warnings ul {
  margin: 1rem 0 0;
  padding-left: 1.25rem;
}

.statistics-warnings li + li {
  margin-top: 0.5rem;
}

.statistics-list,
.event-trace-list {
  display: grid;
  gap: 1rem;
  margin: 1rem 0 0;
  padding: 0;
  list-style: none;
}

.statistic-card,
.event-trace {
  min-width: 0;
  padding: 1.5rem;
  border: 1px solid var(--colour-border);
  border-radius: 6px;
  background: var(--colour-surface);
}

.statistic-card__heading h3,
.event-trace h3 {
  margin: 0.25rem 0 0;
  font-size: 1.25rem;
}

.statistic-card__heading h3 a {
  color: var(--colour-text);
  text-decoration-color: var(--colour-primary);
  text-underline-offset: 0.2em;
}

.statistic-card__association {
  margin-top: 0.5rem !important;
  font-size: 0.875rem;
}

.statistic-metrics,
.event-trace dl {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(8rem, 1fr));
  gap: 1rem;
  margin: 1.25rem 0 0;
}

.statistic-metrics > div,
.event-trace dl > div {
  min-width: 0;
}

.statistic-metrics dt,
.event-trace dt {
  color: var(--colour-text-muted);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
}

.statistic-metrics dd,
.event-trace dd {
  margin: 0.35rem 0 0;
  overflow-wrap: anywhere;
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-weight: 700;
}

.participant-statistics {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.5rem;
}

.participant-statistics h4 {
  margin: 1.25rem 0 0;
}

.player-match-list {
  margin-top: 1rem;
}

.player-match-card__associations {
  margin: 0.5rem 0 0;
  color: var(--colour-text-secondary);
  line-height: 1.6;
}

.player-match-card__notices {
  margin-top: 1.25rem;
  padding: 1rem;
  border-inline-start: 4px solid var(--colour-brand);
  background: var(--colour-surface-raised);
}

.player-match-card__notices h4,
.player-match-card__notices ul {
  margin: 0;
}

.player-match-card__notices ul {
  margin-top: 0.5rem;
  padding-inline-start: 1.25rem;
}

.statistic-card__source-count,
.statistics-note,
.statistics-section__empty {
  margin-top: 1.25rem;
  line-height: 1.6;
}

.statistics-note {
  padding: 1rem;
  border-left: 3px solid var(--colour-data-accent);
  background: var(--colour-surface-raised);
}

@media (max-width: 56.25rem) {
  .site-header__inner {
    grid-template-columns: auto minmax(0, 1fr) auto;
    gap: 0.75rem;
  }

  .site-navigation {
    grid-column: 1 / -1;
    grid-row: 2;
    display: grid;
    grid-template-columns: repeat(5, minmax(0, 1fr));
    width: 100%;
    padding-bottom: 0.75rem;
  }

  .filter-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .record-list__item {
    grid-template-columns: minmax(7rem, 0.7fr) minmax(0, 1.5fr);
  }

  .record-list__summary {
    grid-column: 1 / -1;
  }

  .record-facts {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .admin-user-list {
    grid-template-columns: 1fr;
  }

  .site-header__inner {
    flex-wrap: wrap;
    padding-block: 0.75rem;
  }

  .site-header__controls {
    width: 100%;
    justify-content: space-between;
    order: 2;
  }

  .auth-navigation-wrap {
    min-height: 2.75rem;
  }

  .home-hero {
    min-height: auto;
    background: var(--colour-canvas);
  }

  .home-hero__crease {
    display: none;
  }

  .home-hero__layout,
  .derivation-story__layout,
  .api-feature__layout {
    grid-template-columns: 1fr;
  }

  .home-hero__layout {
    gap: var(--space-10);
    padding-block: var(--space-12);
  }

  .home-hero__visual {
    width: min(100%, 43rem);
    justify-self: center;
  }

  .derivation-story__layout,
  .api-feature__layout {
    gap: var(--space-10);
  }

  .derivation-story__heading {
    position: static;
  }

  .explore-gateway__list li {
    grid-template-columns: 3rem minmax(0, 1fr);
  }

  .explore-gateway__list a {
    grid-column: 2;
  }
}

@media (max-width: 39.9375rem) {
  .site-header__inner,
  .site-footer__inner,
  .content-boundary {
    width: min(100% - 1.5rem, 100rem);
  }

  .site-header__inner {
    min-height: 5rem;
    grid-template-columns: minmax(0, 1fr);
    gap: 0.75rem;
  }

  .site-navigation {
    grid-row: 3;
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .brand-link {
    grid-column: 1;
    grid-row: 1;
    justify-self: start;
  }

  .site-navigation a {
    padding: 0.625rem 0.25rem;
    font-size: 0.75rem;
    overflow-wrap: anywhere;
  }

  .site-header__controls {
    grid-column: 1;
    grid-row: 2;
    align-items: flex-end;
    gap: 0.75rem;
  }

  .auth-navigation {
    flex-wrap: wrap;
  }

  .auth-navigation a,
  .auth-navigation button {
    padding-inline: 0.625rem;
    font-size: 0.875rem;
  }

  .brand-wordmark {
    width: 8.75rem;
  }

  .theme-control {
    gap: 0.5rem;
  }

  .theme-control__label {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
    clip-path: inset(50%);
    white-space: nowrap;
  }

  .theme-control__value {
    min-width: 0;
    max-width: 4.25rem;
    font-size: 0.75rem;
    line-height: 1.1;
  }

  .auth-page {
    min-height: 30rem;
    padding-block: 2.5rem;
  }

  .auth-card {
    padding: 2rem 1.25rem;
  }

  .account-deletion {
    margin-inline: -0.5rem;
    padding: 1.25rem;
  }

  .account-deletion .button--danger,
  .account-deletion__confirmation input {
    width: 100%;
  }

  .submitter-access-panel__heading {
    align-items: flex-start;
    flex-direction: column;
  }

  .submitter-access-panel__message .button,
  .submitter-access-panel__error .button {
    width: 100%;
  }

  .submitter-access-panel__actions {
    display: grid;
  }

  .admin-user-toolbar {
    align-items: stretch;
    flex-direction: column;
  }

  .admin-user-toolbar > div {
    width: 100%;
  }

  .admin-user-toolbar p {
    margin: 0;
    white-space: normal;
  }

  .admin-scope-options {
    grid-template-columns: 1fr;
  }

  .admin-access-form__actions,
  .admin-access-form__actions .button {
    width: 100%;
  }

  h1 {
    max-width: 100%;
    font-size: 2.5rem;
  }

  .home-hero::after {
    width: 5rem;
  }

  .home-hero__layout {
    gap: var(--space-8);
    padding-block: var(--space-10);
  }

  .home-hero h1 {
    max-width: 9ch;
    font-size: clamp(3.2rem, 16vw, 4.25rem);
  }

  .home-hero__summary {
    margin-top: var(--space-5);
    font-size: 1rem;
  }

  .home-hero__actions {
    display: grid;
    margin-top: var(--space-6);
  }

  .home-hero__actions .button {
    width: 100%;
  }

  .home-hero__visual {
    min-height: 23rem;
    aspect-ratio: 0.98;
    border-radius: var(--radius-card);
    clip-path: polygon(0 0, 100% 0, 100% 94%, 91% 100%, 0 100%);
  }

  .hero-scene-fallback {
    padding: 0;
    transform: scale(1.12) translateX(-1.2rem);
  }

  .home-hero__visual-caption {
    top: var(--space-3);
    left: var(--space-3);
    padding: var(--space-2) var(--space-3);
  }

  .home-principles,
  .explore-gateway,
  .derivation-story,
  .api-feature {
    padding-block: var(--space-12);
  }

  .home-section-heading--split {
    grid-template-columns: 1fr;
    gap: var(--space-3);
    padding-bottom: var(--space-6);
  }

  .home-section-heading--split > .eyebrow {
    margin: 0;
  }

  .home-section-heading h2 {
    font-size: 2.5rem;
  }

  .home-principles__list {
    grid-template-columns: 1fr;
  }

  .home-principles__list li,
  .home-principles__list li + li {
    display: grid;
    grid-template-columns: 2.5rem minmax(0, 1fr);
    gap: 0 var(--space-3);
    padding: var(--space-6) 0;
    border-inline-start: 0;
    border-bottom: 1px solid var(--colour-border);
  }

  .home-principles__number {
    grid-row: 1 / span 2;
    margin: var(--space-2) 0 0;
  }

  .home-principles__list h3 {
    font-size: 2.5rem;
  }

  .home-principles__list p {
    max-width: none;
  }

  .derivation-story__layout,
  .api-feature__layout {
    gap: var(--space-8);
  }

  .derivation-flow {
    grid-template-columns: 1fr;
  }

  .derivation-flow__transition {
    min-height: 3rem;
  }

  .derivation-flow__transition span {
    width: 2px;
    height: 2rem;
    margin-inline: auto;
    border-top: 0;
    border-left: 2px solid var(--colour-primary);
  }

  .derivation-flow__transition span::after {
    top: auto;
    right: -3px;
    bottom: 0;
    transform: rotate(135deg);
  }

  .derivation-flow__event,
  .derivation-flow__statistics {
    padding: var(--space-5);
  }

  .derivation-flow__source {
    grid-column: auto;
    padding: var(--space-4);
  }

  .explore-gateway__list li {
    grid-template-columns: 2.5rem minmax(0, 1fr);
    align-items: start;
    gap: var(--space-3);
  }

  .explore-gateway__list a {
    grid-column: 2;
    margin-top: var(--space-2);
  }

  .api-feature__paths li {
    grid-template-columns: 2rem minmax(0, 1fr);
    padding: var(--space-4);
  }

  .home-cta::before {
    left: 82%;
  }

  .home-cta__layout {
    align-items: stretch;
    flex-direction: column;
  }

  .home-cta .button {
    align-self: flex-start;
  }

  .home-cta h2 {
    font-size: 3.4rem;
  }

  h2 {
    font-size: 2rem;
  }

  .site-footer__inner {
    min-height: 9rem;
    align-items: flex-start;
    flex-direction: column;
    justify-content: center;
    gap: 1rem;
  }

  .browse-page {
    padding-bottom: 3.5rem;
  }

  .page-heading {
    padding-block: 1.5rem 1rem;
  }

  .page-heading--detail {
    padding-block: 1rem;
  }

  .page-heading h1 {
    font-size: 2.5rem;
  }

  .filter-panel {
    margin-inline: -0.75rem;
    padding: 1.25rem 0.75rem;
    border-right: 0;
    border-left: 0;
    border-radius: 0;
  }

  .browse-page__content {
    gap: 1.5rem;
  }

  .filter-panel__heading,
  .results-heading {
    align-items: flex-start;
    flex-direction: column;
  }

  .filter-grid,
  .record-facts {
    grid-template-columns: 1fr;
  }

  .record-list__item {
    grid-template-columns: 1fr;
    gap: 0.5rem;
    padding-block: 1.25rem;
  }

  .record-list__summary {
    grid-column: auto;
  }

  .statistics-section-heading,
  .statistic-card__heading,
  .participant-statistics {
    grid-template-columns: 1fr;
    flex-direction: column;
  }

  .statistic-card,
  .event-trace,
  .statistics-warnings {
    padding: 1.25rem;
  }

  .statistic-metrics,
  .event-trace dl {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .pagination,
  .pagination .button {
    width: 100%;
  }

  .pagination__end {
    text-align: left;
  }

  .detail-page {
    padding-block: 1.5rem 3.5rem;
  }

  .submission-page {
    padding-bottom: 3.5rem;
  }

  .admin-users-page {
    padding-bottom: 3.5rem;
  }

  .submission-form {
    gap: 1.5rem;
  }

  .submission-field textarea {
    min-height: 20rem;
    padding: 0.75rem;
    font-size: 0.8125rem;
  }

  .submission-form > .button {
    width: 100%;
  }

  .correction-workspace {
    margin-top: 2rem;
    padding-top: 1.5rem;
  }

  .correction-form {
    margin-inline: -0.75rem;
    padding: 1.25rem 0.75rem;
    border-right: 0;
    border-left: 0;
    border-radius: 0;
  }

  .correction-form__heading,
  .correction-form__grid,
  .correction-event-reference,
  .correction-derived-values {
    grid-template-columns: 1fr;
    flex-direction: column;
  }

  .correction-form__heading > p {
    text-align: left;
  }

  .correction-form > .button,
  .correction-event-picker,
  .correction-event-picker select {
    width: 100%;
  }

  .submission-reference {
    grid-template-columns: 1fr;
  }
}

@media (prefers-reduced-motion: reduce) {
  .hero-scene-fallback,
  .hero-scene {
    transition: none !important;
  }

  .hero-scene-fallback__trail {
    animation: none !important;
  }

  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}

